mapper.select:
SELECT d.id AS id, d.tenant_id AS tenantId, d.bus_no AS busNo, d.status_enum AS statusEnum, d.dispense_enum AS dispenseEnum, d.medication_id AS medicationId, d.patient_id AS patientId, d.encounter_id AS encounterId, d.med_req_id AS medReqId, d.quantity, d.unit_code AS unitCode, d.dispense_quantity AS dispenseQuantity, d.lot_number AS lotNumber, d.preparer_id AS preparerId, d.prepare_time AS prepareTime, d.practitioner_id AS practitionerId, d.dispense_time AS dispenseTime, d.dosage_instruction AS dosageInstruction, d.method_code AS methodCode, d.frequency_code AS frequencyCode, d.dose, d.dose_unit_code AS doseUnitCode, d.summary_no AS summaryNo, m.name AS name, m.merchandise_name AS merchandiseName, m.category_code AS categoryCode, m.total_volume AS totalVolume, m.comprised_text AS comprisedText, m.ingredient, m.approval_number AS approvalNumber, m.skin_test_flag AS skinTestFlag, m.inject_flag AS injectFlag, m.manufacturer_text AS manufacturerText, m.antibiotic_flag AS antibioticFlag, m.rx_flag AS rxFlag, m.dose_form_code AS doseFormCode, m.package_unit_code AS packageUnitCode, m.py_str AS pyStr FROM med_medication_dispense d JOIN med_medication_definition m ON m.id = d.medication_id WHERE d.is_deleted = 0
AND d.patient_id = #{query.patientId}
AND d.encounter_id = #{query.encounterId}
AND d.dispense_enum = #{query.dispenseEnum}
AND d.status_enum = #{query.statusEnum}
AND d.bus_no = #{query.busNo}
ORDER BY d.created_at DESC
